const input = $input.first().json['Notion Database ID or URL'] || '';
const trimmed = input.trim();

const match = trimmed.match(/([a-f0-9]{32})/i);

if (!match) {
  throw new Error('Could not extract a valid Notion Database ID from the input: ' + trimmed);
}

const databaseId = match[1].toLowerCase();

return [{ json: { databaseId } }];

const db = $input.first().json;
const properties = db.properties || {};

const normalizedProperties = Object.keys(properties).map((key) => {
  const prop = properties[key];
  const type = prop.type;
  const typeConfig = prop[type] || {};

  const out = {
    name: key,
    type: type,
    id: prop.id
  };

  if (['select', 'multi_select', 'status'].includes(type)) {
    out.options = (typeConfig.options || []).map(opt => ({ name: opt.name, color: opt.color }));
  }

  if (type === 'relation') {
    out.relatedDatabaseId = typeConfig.database_id;
    out.relationType = typeConfig.type;
  }

  if (type === 'rollup') {
    out.rollupProperty = typeConfig.rollup_property_name;
    out.relationProperty = typeConfig.relation_property_name;
    out.function = typeConfig.function;
  }

  return out;
});

return [{
  json: {
    databaseName: db.title?.[0]?.plain_text || 'Untitled',
    databaseId: db.id,
    propertyCount: normalizedProperties.length,
    schema: normalizedProperties,
    extractedAt: new Date().toLocaleString()
  }
}];

const data = $input.first().json;

// --- Schema Table Rows ---
const rows = data.schema.map(prop => {
  let extra = '';
  if (prop.options) {
    extra = prop.options.map(o => `<span class="badge" style="background:${o.color || '#ccc'}">${o.name}</span>`).join(' ');
  } else if (prop.relatedDatabaseId) {
    extra = `<code>${prop.relatedDatabaseId}</code> (${prop.relationType || ''})`;
  } else if (prop.rollupProperty) {
    extra = `${prop.rollupProperty} via ${prop.relationProperty} → <em>${prop.function}</em>`;
  }
  return `
    <tr>
      <td><strong>${prop.name}</strong></td>
      <td><span class="type-badge type-${prop.type}">${prop.type}</span></td>
      <td><code style="font-size:11px">${prop.id}</code></td>
      <td>${extra}</td>
    </tr>`;
}).join('');

// --- Raw JSON output ---
const exportJson = JSON.stringify([{
  databaseName: data.databaseName,
  databaseId: data.databaseId,
  propertyCount: data.propertyCount,
  schema: data.schema,
  extractedAt: data.extractedAt
}], null, 2);

const escapedJson = exportJson
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Store raw JSON in a JS-safe string for the script tag
const jsJson = exportJson.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');

// --- Full HTML Page ---
const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8"/>
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Schema: ${data.databaseName}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f5f5f5; color: #333; padding: 32px 16px; }
    .card { background: #fff; border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,0.08); max-width: 900px; margin: 0 auto 32px; padding: 32px; }
    h1 { font-size: 22px; margin-bottom: 4px; }
    h2 { font-size: 16px; font-weight: 600; color: #444; margin-bottom: 16px; display: flex; align-items: center; gap: 8px; }
    .meta { font-size: 13px; color: #888; margin-bottom: 24px; }
    .meta code { background: #f0f0f0; padding: 2px 6px; border-radius: 4px; font-size: 12px; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    thead tr { background: #f7f7f7; }
    th { text-align: left; padding: 10px 12px; font-weight: 600; color: #555; border-bottom: 2px solid #eee; }
    td { padding: 9px 12px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }
    tr:hover td { background: #fafafa; }
    .type-badge { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; background: #e8e8e8; color: #444; }
