    .type-rich_text { background: #dcfce7; color: #166534; }
    .type-number { background: #fef9c3; color: #854d0e; }
    .type-select { background: #fce7f3; color: #9d174d; }
    .type-multi_select { background: #ede9fe; color: #5b21b6; }
    .type-date { background: #ffedd5; color: #9a3412; }
    .type-people { background: #cffafe; color: #155e75; }
    .type-relation { background: #f1f5f9; color: #334155; }
    .type-rollup { background: #fef3c7; color: #92400e; }
    .type-formula { background: #e0f2fe; color: #075985; }
    .type-checkbox { background: #d1fae5; color: #065f46; }
    .type-url,.type-email,.type-phone_number { background: #e0e7ff; color: #3730a3; }
    .badge { display: inline-block; padding: 1px 7px; border-radius: 10px; font-size: 11px; margin: 1px; color: #fff; background: #aaa; }
    .footer { margin-top: 20px; font-size: 12px; color: #bbb; text-align: right; }
    .json-wrapper { position: relative; }
    .btn-row { display: flex; gap: 10px; margin-bottom: 12px; }
    .copy-btn, .select-btn {
      background: #6366f1;
      color: #fff;
      border: none;
      border-radius: 6px;
      padding: 8px 18px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }
    .select-btn { background: #475569; }
    .copy-btn:hover { background: #4f46e5; }
    .select-btn:hover { background: #334155; }
    .copy-btn.copied { background: #16a34a; }
    .copy-btn.failed { background: #dc2626; }
    pre#json-output {
      background: #1e1e2e;
      color: #cdd6f4;
      border-radius: 8px;
      padding: 20px 16px;
      font-size: 12.5px;
      line-height: 1.6;
      overflow-x: auto;
      white-space: pre;
      max-height: 480px;
      overflow-y: auto;
      user-select: all;
    }
  </style>
</head>
<body>

  <!-- Schema Table Card -->
  <div class="card">
    <h1>📋 ${data.databaseName}</h1>
    <p class="meta">
      Database ID: <code>${data.databaseId}</code> &nbsp;·&nbsp;
      ${data.propertyCount} properties &nbsp;·&nbsp;
      Extracted: ${data.extractedAt}
    </p>
    <table>
      <thead>
        <tr>
          <th>Property Name</th>
          <th>Type</th>
          <th>ID</th>
          <th>Details</th>
        </tr>
      </thead>
      <tbody>
        ${rows}
      </tbody>
    </table>
    <div class="footer">Generated by Notion Schema Extractor · n8n</div>
  </div>

  <!-- Raw JSON Export Card -->
  <div class="card">
    <h2>🗂️ Raw Schema JSON <span style="font-size:12px;font-weight:400;color:#aaa;">— use this in your other projects</span></h2>
    <div class="btn-row">
      <button class="copy-btn" id="copy-btn" onclick="copyJson()">📋 Copy JSON</button>
      <button class="select-btn" onclick="selectJson()">🖱️ Select All</button>
    </div>
    <div class="json-wrapper">
      <pre id="json-output">${escapedJson}</pre>
    </div>
  </div>

  <script>
    var RAW_JSON = \`${jsJson}\`;

    function showCopied() {
      var btn = document.getElementById('copy-btn');
      btn.textContent = '✓ Copied!';
      btn.classList.add('copied');
      setTimeout(function() {
        btn.textContent = '📋 Copy JSON';
        btn.classList.remove('copied');
      }, 2000);
    }

    function showFailed() {
      var btn = document.getElementById('copy-btn');
      btn.textContent = '✗ Failed — use Select All';
      btn.classList.add('failed');
      setTimeout(function() {
        btn.textContent = '📋 Copy JSON';
        btn.classList.remove('failed');
      }, 3000);
    }

    function selectJson() {
      var pre = document.getElementById('json-output');
      var range = document.createRange();
      range.selectNodeContents(pre);
      var sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    }

    function copyJson() {
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(RAW_JSON)
          .then(function() { showCopied(); })
          .catch(function() { tryExecCopy(); });
      } else {
        tryExecCopy();
      }
    }

    function tryExecCopy() {
      var textarea = document.createElement('textarea');
      textarea.value = RAW_JSON;
      textarea.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none;';
      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();
      var ok = false;
      try { ok = document.execCommand('copy'); } catch(e) {}
      document.body.removeChild(textarea);
      if (ok) { showCopied(); } else { showFailed(); selectJson(); }
    }
  </script>

</body>
</html>`;

